
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe_sol0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe_sol0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.255834810861416e+00, -3.192811012586229e+00, -3.104512708577649e+00, -2.982227957998909e+00, -2.815671360400753e+00, -2.594174855012874e+00, -2.309545684238060e+00, -1.961338492114921e+00, -1.564396674658231e+00, -1.154474723007948e+00, -7.792661241130397e-01, -5.634954600161045e-01, -4.963079700138093e-01, -4.033427932445783e-01, -2.851055954806812e-01, -1.746421640322180e-01, -9.425567327047077e-02, -3.665372383781679e-02, -8.103396302960518e-03, -9.121435000285544e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


